const usableRootGrants = `-- name: UsableRootGrants :many
SELECT g.id, g.instance_id, r.bounds, r.min_attestation, r.expires_at
FROM pc.grants g
JOIN pc.grant_revisions r ON r.org_id = g.org_id AND r.grant_id = g.id AND r.revision = g.current_revision
WHERE g.org_id = $1 AND g.agent_id = $2 AND g.environment_id = $3
  AND g.principal_user_id = $4 AND g.parent_id IS NULL AND g.state = 'ACTIVE'
  AND r.not_before <= now() AND r.expires_at > now()
  AND (g.instance_id IS NULL OR g.instance_id = $5)
ORDER BY g.id
LIMIT 20
`

type UsableRootGrantsParams struct {
	OrgID         ids.OrgID
	AgentID       ids.UUID
	EnvironmentID ids.UUID
	UserID        *ids.UUID
	InstanceID    *ids.UUID
}

type UsableRootGrantsRow struct {
	ID             ids.UUID
	InstanceID     *ids.UUID
	Bounds         []byte
	MinAttestation int16
	ExpiresAt      time.Time
}

// The active, unexpired root grants a person gave this agent in its
// environment. A delegated grant reaches a run only through delegation.
func (q *Queries) UsableRootGrants(ctx context.Context, arg UsableRootGrantsParams) ([]UsableRootGrantsRow, error) {
	rows, err := q.db.Query(ctx, usableRootGrants,
		arg.OrgID,
		arg.AgentID,
		arg.EnvironmentID,
		arg.UserID,
		arg.InstanceID,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []UsableRootGrantsRow{}
	for rows.Next() {
		var i UsableRootGrantsRow
		if err := rows.Scan(
			&i.ID,
			&i.InstanceID,
			&i.Bounds,
			&i.MinAttestation,
			&i.ExpiresAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
